import re

def parse_matrix(text, label):
    m=re.search(re.escape(label)+r'\n([0-9 ]+(?:\n[0-9 ]+){29})', text)
    if not m: raise ValueError(label)
    return [[int(x) for x in ln.split()] for ln in m.group(1).splitlines()]
