from collections import deque

def solve_from_components(grid, panels):
    res=[r[:] for r in grid]
    top_end=panels[0][0]
    for (r0,r1,base,frame) in panels:
        seen=set()
        for r in range(top_end):
            for c in range(len(grid[0])):
                if grid[r][c]!=base or (r,c) in seen: continue
                q=[(r,c)];seen.add((r,c)); comp=[]
                while q:
                    y,x=q.pop();comp.append((y,x))
                    for dy,dx in ((1,0),(-1,0),(0,1),(0,-1)):
                        yy,xx=y+dy,x+dx
                        if 0<=yy<top_end and 0<=xx<len(grid[0]) and grid[yy][xx]==base and (yy,xx) not in seen:
                            seen.add((yy,xx));q.append((yy,xx))
                shift=r1-max(y for y,x in comp)
                for y,x in comp:
                    yy=y+shift
                    if r0<=yy<=r1:
                        res[yy][x]=frame
    return res

